def two_sum(numbers, target):
    ordered = sorted(numbers)
    low = 0
    high = len(ordered) - 1
    while low < high:
        total = ordered[low] + ordered[high]
        if total == target:
            return [low, high]
        if total < target:
            low += 1
        else:
            high -= 1
    return []
